    // create graph for boruvka
    struct Graph* graph = formGraph(V, E);

    if (infile.is_open()) {
        string data[3]; // initialize data array
        int count = 0; // initialize counter

        while (infile.good()) { // same as while not end of file
            getline(infile, line);
            stringstream ssin(line);
