Your code is likely failing because you are using automatic storage. You should use dynamic or static storage. Here is a fix to your code using static storage #include <stdio.h>
#include <stdlib.h>
#define ASIZE 1000

long matrixa [ASIZE][ASIZE];
long matrixb [ASIZE][ASIZE];
long matrixc [ASIZE][ASIZE]; //set to zero by default with static storage

int main() {
    for(int i=0; i<ASIZE; i++) {
        for(int j=0;j<ASIZE; j++) {
            matrixa [i][j] = 1;
            matrixb [i][j] = j;
        }
    }

    #pragma omp parallel for
    for(int i=0 ;i<ASIZE; i++) {
        for(int j=0; j<ASIZE; j++) {
            long sum = 0;
            for(int k=0; k<ASIZE; k++) {
                sum += matrixa[i][k]*matrixb[k][j];
            }
            matrixc[i][j] = sum;
        }
    }
    for(int i=0; i<50; i++) printf("Snap of C array %lu \n", matrixc[1][i]);
} If you want a statically allocated buffer for each thread then you need to use threadprivate otherwise use dynamic allocation. The reason you don't need to use a barrier is that a barrier is implicit with critical and many other constructs. To remove the implicit barrier you can use nowait in some cases (e.g. #pragma omp parallel for nowait ).

