        for(unsigned int i = 0; i < size; ++i)
        {
            resVector[i] = -pairVector[i].first;

            for (unsigned int j = i; j < size; ++j)
            {
                if(pairVector[i].first == pairVector[j].second)
                {
                    resVector[i] = size - j; 
                    break;                                          
                }
            }                                                   
        }
    }

    return resVector;
} Is there anyone seeing what's wrong with that ?? Thank. EDIT: The number of pairs in the vector can be over 1.000.000. The result is the same in both implementations. And even for that size of datas, there is not speed up (even with different schedule types).

answers.body:
The algorithm you are using appears to be O(N^2) but it should be possible in O(NlogN). Even if the O(NlogN) solution is serial, it should still provide a net speedup. Here is an O(NlogN) solution to your problem. The code could be tightened up by better use of STL. #include <algorithm>

std::vector<int> function(std::vector<std::pair<int, int> >& pair_vector) {
    unsigned int size = pair_vector.size();
    std::vector<int> resVector(size);

    std::vector<std::pair<int, int> > firsts(size);
    std::vector<std::pair<int, int> > seconds(size);
    for (int i=0; i<size; i++) {
        firsts[i] = std::pair<int, int>(pair_vector[i].first, i);
        seconds[i] = std::pair<int, int>(pair_vector[i].second, size-i);
    }

    std::sort(firsts.begin(), firsts.end());
    std::sort(seconds.begin(), seconds.end());

    int j=0;
    for (int i=0; i<size; i++) {
      while ((seconds[j].first < firsts[i].first)&&(j<size))
        j++;
      if (seconds[j].first == firsts[i].first)
        resVector[firsts[i].second] = seconds[j].second;
      else
        resVector[firsts[i].second] = -firsts[i].first;
    }

    return resVector;
}

