The answer was: #include <omp.h>
#include <stdio.h>
#include <stdlib.h>

long num_steps = 100000;
double step    = 1.0/100000.0;

int main() {
int i;
double x, pi, sum = 0.0;

#pragma omp parallel private(x) 
{
    #pragma omp for reduction(+:sum)
    for(i = 0; i < num_steps; ++i) {
