    int i;
    pi = 0;
    #pragma omp parallel for schedule(static) reduction(+:pi)
    for (i = 0; i < N; i++) {
        pi += (-2.0f*(i&1)+1)/(2*i+1);
    }
    pi*=4.0f;
    printf("%f\n", pi);   
}

