answers.body:
You re-initialize the random generator in each iteration. That is unlikely to give a good random sequence. Instead, make your generators threadprivate. // global
static random_device rd; 
static mt19937 rng;
#pragma omp threadprivate(rd) 
#pragma omp threadprivate(rng)

// in main, do a parallel seed:
#pragma omp parallel
rng = mt19937(rd());

// anywhere in your program use rng in parallel:
#pragma omp parallel
 {
    stringstream res;
    uniform_int_distribution<int> percent(1, 100);
    res << "Thread " << omp_get_thread_num() << ": " << percent(rng) << "\n";
    cout << res.str();
  }

