void* create(unsigned int size)
{
    void *m = malloc(size);
    memset(m,0,size);
    return m;
}
void create_destory(unsigned int size)
{
    void* p = create(size);
    free(p);
}

int main()
{
    unsigned int mega = 1024 * 1024 * 1024;
    for (int i = 0; i < 4; i++)
    {
        create_destory(mega);
    }
